function fmt(v){return v instanceof Date?Utilities.formatDate(v,Session.getScriptTimeZone(),'yyyy-MM-dd'):v;}
function dump(sheetName, a1){var sh=ss.getSheetByName(sheetName); var rg=sh.getRange(a1); var vals=rg.getValues(); var f=rg.getFormulas(); var out=[]; for(var i=0;i<vals.length;i++){var row=[]; for(var j=0;j<vals[0].length;j++){row.push({r:rg.getRow()+i,c:rg.getColumn()+j,a1:sh.getRange(rg.getRow()+i,rg.getColumn()+j).getA1Notation(),v:fmt(vals[i][j]),f:f[i][j]});} out.push(row);} log(JSON.stringify(out)); }
dump('D&A Schedule','B8:O22');
dump('D&A Schedule','B25:O51');
dump('Operating Valuation','B7:P113');

function col(n){var s=''; while(n>0){var m=(n-1)%26; s=String.fromCharCode(65+m)+s; n=(n-m-1)/26;} return s;}
function setFormulasA1(sh,a1,arr){sh.getRange(a1).setFormulas(arr);} 
var shDA = ss.getSheetByName('D&A Schedule');
var shOV = ss.getSheetByName('Operating Valuation');

// D&A Schedule
// Pre-FY2025P depreciation row 27 and roll-forward row 10
var preDep = [[]], preNet = [[]];
for (var c=5;c<=15;c++) {
  var pc = col(c-1), cc = col(c);
  preDep[0].push('=IF('+pc+'10="",0,MIN('+pc+'10,$D$10/$C$6))');
  preNet[0].push('=MAX('+pc+'10-'+cc+'27,0)');
}
setFormulasA1(shDA,'E27:O27',preDep);
setFormulasA1(shDA,'E10:O10',preNet);

// Forecast PP&E vintages and depreciation
for (var r=11; r<=21; r++) {
  var startCol = r - 6; // E=5 for row11 ... O=15 for row21
  var endCol = 15;
  var netArr=[[]], depArr=[[]];
  for (var c=startCol; c<=endCol; c++) {
    var cc = col(c);
    if (c === startCol) {
      netArr[0].push("=-'Operating Valuation'!"+cc+"57");
      depArr[0].push('=0');
    } else {
      var pc = col(c-1);
      netArr[0].push('=MAX('+pc+r+'-'+cc+(r+17)+',0)');
      depArr[0].push('=IF('+pc+r+'="",0,MIN('+pc+r+',$'+col(startCol)+'$'+r+'/$C$6))');
    }
  }
  shDA.getRange(r, startCol, 1, endCol-startCol+1).setFormulas(netArr);
  shDA.getRange(r+17, startCol, 1, endCol-startCol+1).setFormulas(depArr);
}

// Intangibles roll-forward and amortization
var amort = [[]], intNet = [[]];
for (var c=5;c<=15;c++) {
  var cc = col(c), pc = col(c-1);
  var f;
  if (c<=9) f = '=Drivers!$C$'+(33+c); // E->38 ... I->42
  else f = '=Drivers!$C$43/6';
  amort[0].push(f);
  intNet[0].push('='+pc+'43-'+cc+'45');
}
setFormulasA1(shDA,'E45:O45',amort);
setFormulasA1(shDA,'E43:O43',intNet);

// Operating Valuation
// Growth rows 8-10
for (var r=8; r<=10; r++) {
  var driverStart = 6 + (r-8); // C6,C7,C8
  var driverDelta = 11 + (r-8); // C11,C12,C13
  var arr=[[]];
  for (var c=5;c<=15;c++) {
    var cc=col(c), pc=col(c-1);
    if (c===5) arr[0].push('=Drivers!$C$'+driverStart);
    else arr[0].push('='+pc+r+'+Drivers!$C$'+driverDelta);
  }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
// Aggregate gross bookings growth row 11
var arr11=[[]], arr18=[[]], arr31=[[]], arr46=[[]], arr24=[[]], arr38=[[]], arr62=[[]];
for (var c=5;c<=15;c++) {
  var cc=col(c), pc=col(c-1);
  arr11[0].push('=IFERROR('+cc+'17/'+pc+'17-1,"n/m")');
  arr18[0].push('='+cc+'17/'+pc+'17-1');
  arr31[0].push('='+cc+'30/'+pc+'30-1');
  arr46[0].push('='+cc+'45/'+pc+'45-1');
  arr24[0].push('='+cc+'30/'+cc+'17');
  arr38[0].push('=IFERROR('+cc+'45/'+cc+'30,"n/m")');
  arr62[0].push('=IFERROR('+cc+'61/'+cc+'45,"n/m")');
}
setFormulasA1(shOV,'E11:O11',arr11);
setFormulasA1(shOV,'E18:O18',arr18);
setFormulasA1(shOV,'E31:O31',arr31);
setFormulasA1(shOV,'E46:O46',arr46);
setFormulasA1(shOV,'E24:O24',arr24);
setFormulasA1(shOV,'E38:O38',arr38);
setFormulasA1(shOV,'E62:O62',arr62);

// Gross bookings amounts 14-16
for (var r=14; r<=16; r++) {
  var growthRow = r - 6;
  var arr=[[]];
  for (var c=5;c<=15;c++) {
    var cc=col(c), pc=col(c-1);
    arr[0].push('='+pc+r+'*(1+'+cc+growthRow+')');
  }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
// Totals row 17
var arr17=[[]]; for (var c=5;c<=15;c++){var cc=col(c); arr17[0].push('=SUM('+cc+'14:'+cc+'16)');} setFormulasA1(shOV,'E17:O17',arr17);

// Take rates 21-23
for (var r=21; r<=23; r++) {
  var driver = 16 + (r-21);
  var arr=[[]];
  for (var c=5;c<=15;c++) {
    var pc=col(c-1);
    if (c===5) arr[0].push('=D'+r+'+Drivers!$C$'+driver);
    else arr[0].push('='+pc+r+'+Drivers!$C$'+driver);
  }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
// Revenue rows 27-29
for (var r=27; r<=29; r++) {
  var bookRow = r - 13; // 14-16
  var trRow = r - 6; // 21-23
  var arr=[[]];
  for (var c=5;c<=15;c++) { var cc=col(c); arr[0].push('='+cc+bookRow+'*'+cc+trRow); }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
var arr30=[[]]; for (var c=5;c<=15;c++){var cc=col(c); arr30[0].push('=SUM('+cc+'27:'+cc+'29)');} setFormulasA1(shOV,'E30:O30',arr30);

// EBITDA margins 34-36
for (var r=34; r<=36; r++) {
  var driver = 21 + (r-34);
  var arr=[[]];
  for (var c=5;c<=15;c++) {
    var pc=col(c-1);
    if (c===5) arr[0].push('=D'+r+'+Drivers!$C$'+driver);
    else arr[0].push('='+pc+r+'+Drivers!$C$'+driver);
  }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
// EBITDA amounts 41-43
for (var r=41; r<=43; r++) {
  var revRow = r - 14; // 27-29
  var marginRow = r - 7; // 34-36
  var arr=[[]];
  for (var c=5;c<=15;c++) { var cc=col(c); arr[0].push('='+cc+revRow+'*'+cc+marginRow); }
  shOV.getRange(r,5,1,11).setFormulas(arr);
}
// Corporate overhead 44
var arr44=[[]];
for (var c=5;c<=15;c++) { var pc=col(c-1); arr44[0].push('='+pc+'44*(1+Drivers!$C$26)'); }
setFormulasA1(shOV,'E44:O44',arr44);
var arr45=[[]]; for (var c=5;c<=15;c++){var cc=col(c); arr45[0].push('=SUM('+cc+'41:'+cc+'44)');} setFormulasA1(shOV,'E45:O45',arr45);

// D&A, taxes, SBC, CapEx, NWC, add-back
var arr48=[[]], arr52=[[]], arr56=[[]], arr57=[[]], arr58=[[]], arr59=[[]];
for (var c=5;c<=15;c++) {
  var cc=col(c), pc=col(c-1);
  arr48[0].push("=-'D&A Schedule'!"+cc+"51");
  arr52[0].push('=-'+cc+'50*Drivers!$C$29');
  arr56[0].push('=-'+cc+'17*Drivers!$C$49');
  arr57[0].push('=-'+cc+'17*Drivers!$C$32');
  arr58[0].push('=-('+cc+'17-'+pc+'17)*Drivers!$C$46');
  arr59[0].push('=-'+cc+'48');
}
setFormulasA1(shOV,'E48:O48',arr48);
setFormulasA1(shOV,'E52:O52',arr52);
setFormulasA1(shOV,'E56:O56',arr56);
setFormulasA1(shOV,'E57:O57',arr57);
setFormulasA1(shOV,'E58:O58',arr58);
setFormulasA1(shOV,'E59:O59',arr59);

// DCF summaries
shOV.getRange('C73').setFormula('=SUM(E69:O69)');
shOV.getRange('C74').setFormula('=P69');
shOV.getRange('C76').setFormula('=C75/E45');
shOV.getRange('C79').setFormula('=SUM(E69:O69)');
shOV.getRange('C80').setFormula('=($O$61*(1+$C$88))/($C$85-$C$88)*$P$67');
shOV.getRange('C82').setFormula('=C81/E45');

// Sensitivity grids outputs only
var sensExit=[];
for (var r=99;r<=103;r++) {
  var row=[];
  for (var c=4;c<=8;c++) {
    var cc=col(c);
    row.push('=SUMPRODUCT($E$64:$O$64,1/((1+'+cc+'$98)^$E$66:$O$66))+($P$45*$C'+r+')/((1+'+cc+'$98)^$P$66)');
  }
  sensExit.push(row);
}
shOV.getRange('D99:H103').setFormulas(sensExit);
var sensPgr=[];
for (var r=109;r<=113;r++) {
  var row=[];
  for (var c=4;c<=8;c++) {
    var cc=col(c);
    row.push('=SUMPRODUCT($E$64:$O$64,1/((1+'+cc+'$108)^$E$66:$O$66))+(($O$61*(1+$C'+r+'))/('+cc+'$108-$C'+r+'))/((1+'+cc+'$108)^$P$66)');
  }
  sensPgr.push(row);
}
shOV.getRange('D109:H113').setFormulas(sensPgr);

SpreadsheetApp.flush();

function logRange(a1){ var rg=shOV.getRange(a1); log(a1+': '+JSON.stringify({vals:rg.getDisplayValues(), formulas:rg.getFormulas()})); }
function logRangeDA(a1){ var rg=shDA.getRange(a1); log('DA '+a1+': '+JSON.stringify({vals:rg.getDisplayValues(), formulas:rg.getFormulas()})); }
logRangeDA('D10:I12');
logRangeDA('D27:J28');
logRangeDA('D43:O45');
logRange('D8:O18');
logRange('D21:O31');
logRange('D34:O62');
logRange('C73:C82');
logRange('C98:H103');
logRange('C108:H113');

function show(sheet,a1){var rg=ss.getSheetByName(sheet).getRange(a1); log(sheet+' '+a1+' '+JSON.stringify({disp:rg.getDisplayValues(), formulas:rg.getFormulas()}));}
show('D&A Schedule','E22:O22');
show('D&A Schedule','E39:O39');
show('D&A Schedule','E51:O51');
show('Operating Valuation','E48:O61');
show('Operating Valuation','E64:P69');
